def _create_guards(apps: Any, schema_editor: Any) -> None:
    """Los disparadores vigilan al rol del runtime (`crm_app`): quien migra o mantiene la base
    como `crm_migrator` (una migración de datos, el borrado de una organización) no pasa por
    ellos, y `crm_app` no puede quitárselos: no es dueño de las tablas."""
    for table, name, when, function in TRIGGERS:
        schema_editor.execute(function.replace("__APP__", settings.DB_APP_ROLE))
        schema_editor.execute(
            f"CREATE TRIGGER {name} {when} ON public.{table} FOR EACH ROW EXECUTE FUNCTION {name}()"
        )


def _drop_guards(apps: Any, schema_editor: Any) -> None:
    for table, name, _, _ in reversed(TRIGGERS):
        schema_editor.execute(f"DROP TRIGGER IF EXISTS {name} ON public.{table}")
        schema_editor.execute(f"DROP FUNCTION IF EXISTS {name}()")


def _privileges(apps: Any, schema_editor: Any) -> None:
    """Una aprobación no se borra (es historia) y la política es configuración: se cambia, no se
    vacía."""
    role = schema_editor.quote_name(settings.DB_APP_ROLE)
    schema_editor.execute(f"REVOKE DELETE, TRUNCATE ON public.quote_approvals FROM {role}")
    schema_editor.execute(f"REVOKE TRUNCATE ON public.discount_policies FROM {role}")


def _restore(apps: Any, schema_editor: Any) -> None:
    role = schema_editor.quote_name(settings.DB_APP_ROLE)
    for table in ("quote_approvals", "discount_policies"):
        schema_editor.execute(f"GRANT SELECT, INSERT, UPDATE, DELETE ON public.{table} TO {role}")


